export function approvalSummary(name:string,args:any,description:string){
  const titles:Record<string,string>={'browser.commit':'Підтвердити дію на сторінці','access.grant_read':'Дозволити читання власного підключення','connector.call':'Виконати дію у твоєму підключенні','library.destination':'Дозволити погоджені публікації в каналі','library.publish':'Надіслати вибраний файл','calendar.write':'Змінити подію в особистому календарі'};
  const lines=[titles[name]||description.split(/\.\s/u)[0]||'Підтвердити дію'];
  const pending=Object.entries(args as Record<string,unknown>).reverse().map(([key,value])=>({key,value,depth:0}));
  while(pending.length){
    const item=pending.pop()!;let value=item.value;
    if(item.key==='arguments'&&typeof value==='string')try{value=JSON.parse(value);}catch{}
    const indent=item.depth<=8?'  '.repeat(item.depth):`[рівень ${item.depth+1}] `,label=approvalLabels[item.key]||item.key;
    if(value&&typeof value==='object'){
      const entries=Object.entries(value);
      lines.push(`${indent}${label}:${entries.length?'':Array.isArray(value)?' порожній список':' порожній об’єкт'}`);
      for(const [key,entry] of entries.reverse())pending.push({key:Array.isArray(value)?String(Number(key)+1):key,value:entry,depth:item.depth+1});
    }else lines.push(`${indent}${label}: ${value===null?'null (порожнє значення)':value===undefined?'не задано':typeof value==='boolean'?value?'так':'ні':value===''?'«»':String(value)}`);
  }
  if(name==='connector.call')lines.push(args.share_result?'Відповідь сервісу дозволено показати цій групі.':'Відповідь сервісу отримаєш особисто.');
  return lines.join('\n');
}
